INSERT INTO public.flashcards (id, deck_id, front_text, back_text, mnemonics, exam_relevance, order_index)
VALUES
  ('c0000010000-4000-8000-000000000001'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Which Texas agency licenses cosmetologists?', 'Texas Department of Licensing and Regulation (TDLR) — verify current rules on TDLR.texas.gov before your exam.', 'TDLR = Texas licenses', 5, 1),
  ('c0000020000-4000-8000-000000000002'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Texas cosmetology written exam vendor (typical)?', 'NIC (National-Interstate Council) examinations are commonly used — confirm your school’s candidate handbook.', NULL, 5, 2),
  ('c0000030000-4000-8000-000000000003'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'EPA-registered disinfectant contact time on pre-cleaned implements?', 'Follow the product label exactly — most require 10 minutes wet contact on a clean, dry surface.', NULL, 5, 3),
  ('c0000040000-4000-8000-000000000004'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'When must you wash hands in Texas practice?', 'Before each client, after restroom use, when visibly soiled, and before/after gloves if used.', NULL, 4, 4),
  ('c0000050000-4000-8000-000000000005'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Blood exposure on a work surface — first step?', 'Stop service, put on gloves, block off area, clean with EPA-registered bloodborne pathogen cleaner per label.', NULL, 5, 5),
  ('c0000060000-4000-8000-000000000006'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Multi-use metal tools after a haircut — minimum process?', 'Remove debris, wash with detergent, rinse, dry, then immerse in EPA-registered disinfectant for label time.', NULL, 5, 6),
  ('c0000070000-4000-8000-000000000007'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Single-use porous items (neck strips, cotton) after one client?', 'Discard immediately — never reuse on another client.', NULL, 5, 7),
  ('c0000080000-4000-8000-000000000008'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'UV sterilizer (cabinet) — acceptable alone for implements?', 'No — UV cabinets are not a substitute for liquid chemical disinfection or sterilization where required.', NULL, 4, 8),
  ('c0000090000-4000-8000-000000000009'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Texas booth rental — who maintains sanitation logs?', 'The license holder performing services is responsible for their station, tools, and disinfectant records.', NULL, 3, 9),
  ('c0000100000-4000-8000-000000000010'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Disinfectant solution strength — how do you maintain it?', 'Mix fresh per manufacturer directions; change when visibly dirty or per label — never “top off” indefinitely.', NULL, 4, 10),
  ('c0000110000-4000-8000-000000000011'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Contact dermatitis from disinfectant — best action?', 'Switch to compatible gloves, improve ventilation, use labeled product; seek medical care if severe.', NULL, 3, 11),
  ('c0000120000-4000-8000-000000000012'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Foot spa basin — between clients?', 'Drain, scrub, rinse, disinfect per manufacturer; log if your salon policy requires.', NULL, 5, 12),
  ('c0000130000-4000-8000-000000000013'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Sharps (lancets, needles) in Texas cosmetology scope?', 'Only if your license and training authorize — never discard loose in trash; use sharps container.', NULL, 4, 13),
  ('c0000140000-4000-8000-000000000014'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Client with open wound on scalp — what should you do?', 'Do not perform chemical services; postpone or refer; document refusal if needed.', NULL, 4, 14),
  ('c0000150000-4000-8000-000000000015'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Material Safety Data Sheet / SDS — purpose?', 'Explains hazards, PPE, first aid for salon chemicals — keep accessible per OSHA expectations.', NULL, 3, 15),
  ('c0000160000-4000-8000-000000000016'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Clean vs. sanitized vs. sterilized?', 'Clean = soil removed; sanitized = pathogens reduced on surfaces; sterilized = destruction of all microbial life (autoclave).', NULL, 5, 16),
  ('c0000170000-4000-8000-000000000017'::uuid, 'b1000001-0001-4001-8001-000000000101'::uuid, 'Texas cosmetology hour total (verify before testing)?', 'Program hours are set by TDLR rule — schools publish current totals (often 1,000 hours for operator; confirm with TDLR).', NULL, 4, 17),
  ('c0000180000-4000-8000-000000000018'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Level system on hair color box — what does “7” mean?', 'Medium blonde depth on the 1–10 scale (1 black, 10 lightest blonde).', NULL, 5, 1),
  ('c0000190000-4000-8000-000000000019'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Underlying pigment at level 6 (light brown)?', 'Red-orange — explains why ash formulas can look muddy without pre-lightening.', NULL, 4, 2),
  ('c0000200000-4000-8000-000000000020'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Developer 20 volume — typical use?', 'Up to 2 levels lift on scalp, deposit on previously colored hair, gray coverage with permanent color.', NULL, 5, 3),
  ('c0000210000-4000-8000-000000000021'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Developer 30 volume — caution?', 'More lift and potential damage; not default on scalp for fine or previously lightened hair.', NULL, 4, 4),
  ('c0000220000-4000-8000-000000000022'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Equal parts color + 20 vol on regrowth only — why?', 'Controls heat from scalp, targets new growth without over-processing mids/ends.', NULL, 4, 5),
  ('c0000230000-4000-8000-000000000023'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Patch test wait time (standard)?', '48 hours before full application when manufacturer or state rule requires.', NULL, 5, 6),
  ('c0000240000-4000-8000-000000000024'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Warm tone neutralized by?', 'Ash / green-based toners on the color wheel (opposite complements).', NULL, 4, 7),
  ('c0000250000-4000-8000-000000000025'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Brassy orange after bleach — first toner choice?', 'Blue-based ash toner (blue cancels orange on the wheel).', NULL, 5, 8),
  ('c0000260000-4000-8000-000000000026'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Porosity test — hair floats quickly?', 'High porosity — absorbs fast, may look dull; use lower developer, fillers, or protein treatments.', NULL, 4, 9),
  ('c0000270000-4000-8000-000000000027'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Demi-permanent vs. permanent?', 'Demi deposits with low/no lift, fades off; permanent uses alkalizer, lifts, and leaves lasting pigment.', NULL, 5, 10),
  ('c0000280000-4000-8000-000000000028'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Fillers before fashion vivids on level 10?', 'Replace missing gold/orange stages so direct dye adheres evenly.', NULL, 3, 11),
  ('c0000290000-4000-8000-000000000029'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Texas law — who can mix professional color?', 'Licensed cosmetologists (or students under instructor) — not unlicensed assistants alone.', NULL, 3, 12),
  ('c0000300000-4000-8000-000000000030'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Overlapping permanent color on previously colored hair?', 'Causes banding and breakage — apply to regrowth only, refresh ends with gloss if needed.', NULL, 5, 13),
  ('c0000310000-4000-8000-000000000031'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'pH of hydroxide relaxer?', 'Very high (alkaline) — swells cuticle, breaks disulfide bonds; requires neutralizer after.', NULL, 4, 14),
  ('c0000320000-4000-8000-000000000032'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Strand test purpose before lightening?', 'Predict lift, damage, and timing — mandatory on compromised hair.', NULL, 5, 15),
  ('c0000330000-4000-8000-000000000033'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Green cast on pool hair — remove with?', 'Red-based shampoo or chelating treatment (complementary to green).', NULL, 3, 16),
  ('c0000340000-4000-8000-000000000034'::uuid, 'b1000002-0002-4002-8002-000000000102'::uuid, 'Consultation question for color correction?', 'History: box color, henna, relaxer, meds, last lightening — all affect outcome.', NULL, 5, 17),
  ('c0000350000-4000-8000-000000000035'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Epidermis function for esthetics/cosmetology?', 'Outermost layer — protection, melanin production, cell turnover.', NULL, 4, 1),
  ('c0000360000-4000-8000-000000000036'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Dermis contains?', 'Collagen, elastin, blood vessels, nerves, hair follicles, sweat/oil glands.', NULL, 4, 2),
  ('c0000370000-4000-8000-000000000037'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Arrector pili muscle — effect?', 'Pulls hair upright (“goosebumps”) when cold or frightened.', NULL, 3, 3),
  ('c0000380000-4000-8000-000000000038'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Hair growth phase — longest?', 'Anagen (active growth) — can last years on scalp.', NULL, 5, 4),
  ('c0000390000-4000-8000-000000000039'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Catagen phase?', 'Short transition — follicle shrinks, detaches from dermal papilla.', NULL, 4, 5),
  ('c0000400000-4000-8000-000000000040'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Telogen phase?', 'Resting — club hair sheds, new anagen begins.', NULL, 4, 6),
  ('c0000410000-4000-8000-000000000041'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Chemical hair bond broken by permanent wave solution?', 'Disulfide bonds — reshaped on rods, reformed with neutralizer.', NULL, 5, 7),
  ('c0000420000-4000-8000-000000000042'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Hydrogen bonds in hair?', 'Weak, broken by water/heat — explain blow-dry styling and humidity frizz.', NULL, 4, 8),
  ('c0000430000-4000-8000-000000000043'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Oval follicle produces?', 'Wavy hair cross-section.', NULL, 3, 9),
  ('c0000440000-4000-8000-000000000044'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Flat follicle produces?', 'Straight, coarse hair typical of many Asian hair types.', NULL, 3, 10),
  ('c0000450000-4000-8000-000000000045'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Round follicle produces?', 'Straight, finer strands common in many European hair types.', NULL, 3, 11),
  ('c0000460000-4000-8000-000000000046'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Nail plate growth zone?', 'Matrix under proximal nail fold — damage here affects permanent nail shape.', NULL, 4, 12),
  ('c0000470000-4000-8000-000000000047'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Onycholysis?', 'Separation of nail plate from bed — avoid aggressive filing; refer if infection suspected.', NULL, 4, 13),
  ('c0000480000-4000-8000-000000000048'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Contraindication for chemical relaxer?', 'Scalp abrasion, active infection, previous incompatible chemical service same day.', NULL, 5, 14),
  ('c0000490000-4000-8000-000000000049'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Bacteria vs. virus — salon relevance?', 'Bacteria on tools/surfaces (disinfect); viruses like bloodborne pathogens need barrier precautions.', NULL, 4, 15),
  ('c0000500000-4000-8000-000000000050'::uuid, 'b1000003-0003-4003-8003-000000000103'::uuid, 'Cocci bacteria shape?', 'Round clusters/chains — common skin flora; sanitation prevents spread.', NULL, 3, 16),
  ('c0000510000-4000-8000-000000000051'::uuid, 'b2000001-0001-4001-8001-000000000201'::uuid, 'Which California agency regulates cosmetology?', 'Board of Barbering and Cosmetology (BBC) — rules at barbercosmo.ca.gov.', 'BBC = California board', 5, 1),
  ('c0000520000-4000-8000-000000000052'::uuid, 'b2000001-0001-4001-8001-000000000201'::uuid, 'California cosmetologist training hours (verify current)?', 'BBC programs typically require 1,600 hours for cosmetologist licensure — confirm with your school.', NULL, 5, 2),
  ('c0000530000-4000-8000-000000000053'::uuid, 'b2000001-0001-4001-8001-000000000201'::uuid, 'EPA-registered disinfectant contact time on pre-cleaned implements?', 'Follow the product label exactly — most require 10 minutes wet contact on a clean, dry surface.', NULL, 5, 3),
  ('c0000540000-4000-8000-000000000054'::uuid, 'b2000001-0001-4001-8001-000000000201'::uuid, 'When must you wash hands in Texas practice?', 'Before each client, after restroom use, when visibly soiled, and before/after gloves if used.', NULL, 4, 4),
  ('c0000550000-4000-8000-000000000055'::uuid, 'b2000001-0001-4001-8001-000000000201'::uuid, 'Blood exposure on a work surface — first step?', 'Stop service, put on gloves, block off area, clean with EPA-registered bloodborne pathogen cleaner per label.', NULL, 5, 5),
