  ('c0000670000-4000-8000-000000000067'::uuid, 'b2000001-0001-4001-8001-000000000201'::uuid, 'California disinfectant — acceptable types?', 'EPA-registered bactericidal, virucidal, fungicidal disinfectants used per label on pre-cleaned tools.', NULL, 5, 17),
