  ('c0000790000-4000-8000-000000000079'::uuid, 'b2000002-0002-4002-8002-000000000202'::uuid, 'California — who may perform hair coloring?', 'Licensed cosmetologists or barbers within scope; estheticians only where BBC scope allows.', NULL, 4, 12),
