  ('c0001010000-4000-8000-000000000101'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Which Florida department licenses cosmetology?', 'Florida DBPR — Cosmetology program under Division of Professions.', 'DBPR Florida', 5, 1),
  ('c0001020000-4000-8000-000000000102'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Florida cosmetology exam vendor (typical)?', 'NIC or PSI depending on license type — use your candidate handbook.', NULL, 5, 2),
