  ('c0001060000-4000-8000-000000000106'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Multi-use metal tools after a haircut — minimum process?', 'Remove debris, wash with detergent, rinse, dry, then immerse in EPA-registered disinfectant for label time.', NULL, 5, 6),
  ('c0001070000-4000-8000-000000000107'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Single-use porous items (neck strips, cotton) after one client?', 'Discard immediately — never reuse on another client.', NULL, 5, 7),
  ('c0001080000-4000-8000-000000000108'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'UV sterilizer (cabinet) — acceptable alone for implements?', 'No — UV cabinets are not a substitute for liquid chemical disinfection or sterilization where required.', NULL, 4, 8),
  ('c0001090000-4000-8000-000000000109'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Texas booth rental — who maintains sanitation logs?', 'The license holder performing services is responsible for their station, tools, and disinfectant records.', NULL, 3, 9),
  ('c0001100000-4000-8000-000000000110'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Disinfectant solution strength — how do you maintain it?', 'Mix fresh per manufacturer directions; change when visibly dirty or per label — never “top off” indefinitely.', NULL, 4, 10),
  ('c0001110000-4000-8000-000000000111'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Contact dermatitis from disinfectant — best action?', 'Switch to compatible gloves, improve ventilation, use labeled product; seek medical care if severe.', NULL, 3, 11),
  ('c0001120000-4000-8000-000000000112'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Foot spa basin — between clients?', 'Drain, scrub, rinse, disinfect per manufacturer; log if your salon policy requires.', NULL, 5, 12),
  ('c0001130000-4000-8000-000000000113'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Sharps (lancets, needles) in Texas cosmetology scope?', 'Only if your license and training authorize — never discard loose in trash; use sharps container.', NULL, 4, 13),
  ('c0001140000-4000-8000-000000000114'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Client with open wound on scalp — what should you do?', 'Do not perform chemical services; postpone or refer; document refusal if needed.', NULL, 4, 14),
  ('c0001150000-4000-8000-000000000115'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Material Safety Data Sheet / SDS — purpose?', 'Explains hazards, PPE, first aid for salon chemicals — keep accessible per OSHA expectations.', NULL, 3, 15),
  ('c0001160000-4000-8000-000000000116'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Clean vs. sanitized vs. sterilized?', 'Clean = soil removed; sanitized = pathogens reduced on surfaces; sterilized = destruction of all microbial life (autoclave).', NULL, 5, 16),
  ('c0001170000-4000-8000-000000000117'::uuid, 'b3000001-0001-4001-8001-000000000301'::uuid, 'Florida cosmetology program hours (verify)?', 'Full cosmetology programs are commonly 1,200 clock hours — confirm with DBPR and your school.', NULL, 4, 17),
  ('c0001180000-4000-8000-000000000118'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Level system on hair color box — what does “7” mean?', 'Medium blonde depth on the 1–10 scale (1 black, 10 lightest blonde).', NULL, 5, 1),
  ('c0001190000-4000-8000-000000000119'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Underlying pigment at level 6 (light brown)?', 'Red-orange — explains why ash formulas can look muddy without pre-lightening.', NULL, 4, 2),
  ('c0001200000-4000-8000-000000000120'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Developer 20 volume — typical use?', 'Up to 2 levels lift on scalp, deposit on previously colored hair, gray coverage with permanent color.', NULL, 5, 3),
  ('c0001210000-4000-8000-000000000121'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Developer 30 volume — caution?', 'More lift and potential damage; not default on scalp for fine or previously lightened hair.', NULL, 4, 4),
  ('c0001220000-4000-8000-000000000122'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Equal parts color + 20 vol on regrowth only — why?', 'Controls heat from scalp, targets new growth without over-processing mids/ends.', NULL, 4, 5),
  ('c0001230000-4000-8000-000000000123'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Patch test wait time (standard)?', '48 hours before full application when manufacturer or state rule requires.', NULL, 5, 6),
  ('c0001240000-4000-8000-000000000124'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Warm tone neutralized by?', 'Ash / green-based toners on the color wheel (opposite complements).', NULL, 4, 7),
  ('c0001250000-4000-8000-000000000125'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Brassy orange after bleach — first toner choice?', 'Blue-based ash toner (blue cancels orange on the wheel).', NULL, 5, 8),
  ('c0001260000-4000-8000-000000000126'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Porosity test — hair floats quickly?', 'High porosity — absorbs fast, may look dull; use lower developer, fillers, or protein treatments.', NULL, 4, 9),
  ('c0001270000-4000-8000-000000000127'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Demi-permanent vs. permanent?', 'Demi deposits with low/no lift, fades off; permanent uses alkalizer, lifts, and leaves lasting pigment.', NULL, 5, 10),
  ('c0001280000-4000-8000-000000000128'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Fillers before fashion vivids on level 10?', 'Replace missing gold/orange stages so direct dye adheres evenly.', NULL, 3, 11),
  ('c0001290000-4000-8000-000000000129'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Florida — chemical service documentation?', 'Maintain client consultation records; follow DBPR sanitation and scope rules for chemical services.', NULL, 3, 12),
  ('c0001300000-4000-8000-000000000130'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Overlapping permanent color on previously colored hair?', 'Causes banding and breakage — apply to regrowth only, refresh ends with gloss if needed.', NULL, 5, 13),
  ('c0001310000-4000-8000-000000000131'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'pH of hydroxide relaxer?', 'Very high (alkaline) — swells cuticle, breaks disulfide bonds; requires neutralizer after.', NULL, 4, 14),
  ('c0001320000-4000-8000-000000000132'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Strand test purpose before lightening?', 'Predict lift, damage, and timing — mandatory on compromised hair.', NULL, 5, 15),
  ('c0001330000-4000-8000-000000000133'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Green cast on pool hair — remove with?', 'Red-based shampoo or chelating treatment (complementary to green).', NULL, 3, 16),
  ('c0001340000-4000-8000-000000000134'::uuid, 'b3000002-0002-4002-8002-000000000302'::uuid, 'Consultation question for color correction?', 'History: box color, henna, relaxer, meds, last lightening — all affect outcome.', NULL, 5, 17),
  ('c0001350000-4000-8000-000000000135'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Epidermis function for esthetics/cosmetology?', 'Outermost layer — protection, melanin production, cell turnover.', NULL, 4, 1),
  ('c0001360000-4000-8000-000000000136'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Dermis contains?', 'Collagen, elastin, blood vessels, nerves, hair follicles, sweat/oil glands.', NULL, 4, 2),
  ('c0001370000-4000-8000-000000000137'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Arrector pili muscle — effect?', 'Pulls hair upright (“goosebumps”) when cold or frightened.', NULL, 3, 3),
  ('c0001380000-4000-8000-000000000138'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Hair growth phase — longest?', 'Anagen (active growth) — can last years on scalp.', NULL, 5, 4),
  ('c0001390000-4000-8000-000000000139'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Catagen phase?', 'Short transition — follicle shrinks, detaches from dermal papilla.', NULL, 4, 5),
  ('c0001400000-4000-8000-000000000140'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Telogen phase?', 'Resting — club hair sheds, new anagen begins.', NULL, 4, 6),
  ('c0001410000-4000-8000-000000000141'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Chemical hair bond broken by permanent wave solution?', 'Disulfide bonds — reshaped on rods, reformed with neutralizer.', NULL, 5, 7),
  ('c0001420000-4000-8000-000000000142'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Hydrogen bonds in hair?', 'Weak, broken by water/heat — explain blow-dry styling and humidity frizz.', NULL, 4, 8),
  ('c0001430000-4000-8000-000000000143'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Oval follicle produces?', 'Wavy hair cross-section.', NULL, 3, 9),
  ('c0001440000-4000-8000-000000000144'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Flat follicle produces?', 'Straight, coarse hair typical of many Asian hair types.', NULL, 3, 10),
  ('c0001450000-4000-8000-000000000145'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Round follicle produces?', 'Straight, finer strands common in many European hair types.', NULL, 3, 11),
  ('c0001460000-4000-8000-000000000146'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Nail plate growth zone?', 'Matrix under proximal nail fold — damage here affects permanent nail shape.', NULL, 4, 12),
  ('c0001470000-4000-8000-000000000147'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Onycholysis?', 'Separation of nail plate from bed — avoid aggressive filing; refer if infection suspected.', NULL, 4, 13),
  ('c0001480000-4000-8000-000000000148'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Contraindication for chemical relaxer?', 'Scalp abrasion, active infection, previous incompatible chemical service same day.', NULL, 5, 14),
  ('c0001490000-4000-8000-000000000149'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Bacteria vs. virus — salon relevance?', 'Bacteria on tools/surfaces (disinfect); viruses like bloodborne pathogens need barrier precautions.', NULL, 4, 15),
  ('c0001500000-4000-8000-000000000150'::uuid, 'b3000003-0003-4003-8003-000000000303'::uuid, 'Cocci bacteria shape?', 'Round clusters/chains — common skin flora; sanitation prevents spread.', NULL, 3, 16)
